 String[] logs(){String log=Engine.log(this);ArrayList<String> valid=new ArrayList<>();for(String line:log.split("\n")){int separator=line.indexOf('|');if(separator<1)continue;try{long timestamp=Long.parseLong(line.substring(0,separator));if(timestamp<=0)continue;}catch(NumberFormatException ignored){continue;}String event=line.substring(separator+1).trim();String lower=event.toLowerCase(java.util.Locale.ROOT);if(event.isEmpty()||lower.contains("fixture")||lower.contains("demo")||lower.contains("controlled")||lower.contains("screen review rendered")||lower.contains("gateway")||lower.contains("action sent")||lower.contains("action effect")||lower.contains("picker")||lower.contains("source screen")||lower.contains("source rejected")||lower.contains("exact source")||lower.contains("expected effect")||lower.contains("original store"))continue;valid.add(line);}return valid.toArray(new String[0]);}void stats(LinearLayout parent){LinearLayout r=row();int verified=0;for(String l:logs())if(l.contains("effect verified"))verified++;for(String s:new String[]{logs().length+"\nRecords",verified+"\nVerified actions",serviceStatus()+"\nService"}){TextView t=text(s,13,-1,true);t.setGravity(17);t.setPadding(d(8),d(12),d(8),d(12));GradientDrawable summaryBackground=Design.shape(0xff293653,d(12));summaryBackground.setStroke(d(1),0x354f628d);t.setBackground(summaryBackground);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,d(72),1);p.rightMargin=d(5);r.addView(t,p);}parent.addView(r);}
