 void settings(){LinearLayout preferences=group("Preferences","Settings are stored on this device.","settings");item(preferences,"Apps","Manage apps","Review selected apps and recognition preferences","",()->go("Manage Apps"));item(preferences,"shield","Permissions & privacy","Review access and optional AI consent","",()->go("Permissions"));toggle(preferences,"Pause background service","Retain original retailer screens",Engine.paused(this),true,b->{if(b!=Engine.paused(this))pause();});LinearLayout data=group("Local data","Manage your history and saved app choices.","lock");item(data,"Activity","Clear activity history","Delete records from this device","",()->clearHistory());item(data,"settings","Reset local preferences","Remove app opt-ins and disable optional AI","",()->new AlertDialog.Builder(this).setMessage("Reset app opt-ins and optional review preferences? Activity history will remain.").setNegativeButton("Cancel",null).setPositiveButton("Reset",(a,b)->{SharedPreferences p=getSharedPreferences("cc",0);SharedPreferences.Editor editor=p.edit();for(String key:p.getAll().keySet())if(key.startsWith("allow:")||key.equals("selected_apps")||key.equals("ai_enabled"))editor.remove(key);editor.putBoolean("paused",true).apply();sendBroadcast(new Intent("com.clearchoice.PAUSE_CHANGED").setPackage(getPackageName()));render();}).show());}
